     with f.open('rb')as inp:
      start=time.perf_counter_ns();subprocess.run(['taskset','-c','14',str(out/(m+'_'+v))],stdin=inp,stdout=subprocess.DEVNULL,check=True);data[m][f.stem][v].append((time.perf_counter_ns()-start)/1e6)
